package main

import (
	"net/http"
	"strings"

	"github.com/router-for-me/CLIProxyAPI/v7/sdk/pluginapi"
)

const quotaDashboardHTML = `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>API Key 额度</title>
<style>
:root{color-scheme:light dark;--bg:#f5f7fb;--panel:#fff;--text:#172033;--muted:#697386;--line:#dde3ec;--accent:#2563eb;--danger:#dc2626;--ok:#059669;--warn:#d97706}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{max-width:1180px;margin:0 auto;padding:28px 18px 50px}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:20px}h1{margin:0 0 6px;font-size:28px}.sub{color:var(--muted);max-width:780px}.actions{display:flex;gap:9px;flex-wrap:wrap}button,a.button{border:1px solid var(--line);border-radius:9px;background:var(--panel);color:var(--text);padding:9px 13px;text-decoration:none;cursor:pointer;font-weight:650}button.primary{background:var(--accent);border-color:var(--accent);color:white}button.danger{color:var(--danger)}button:disabled{opacity:.55;cursor:not-allowed}.notice{margin:0 0 16px;padding:12px 14px;border:1px solid #f0c36d;border-radius:10px;background:color-mix(in srgb,#fef3c7 70%,var(--panel));color:color-mix(in srgb,var(--text) 80%,#92400e)}.error{display:none;margin:0 0 14px;padding:11px 13px;border:1px solid #fecaca;border-radius:9px;background:#fef2f2;color:#991b1b}.error.show{display:block}.panel{overflow:hidden;border:1px solid var(--line);border-radius:13px;background:var(--panel);box-shadow:0 4px 16px rgb(15 23 42/.05)}table{width:100%;border-collapse:collapse}th,td{padding:13px 14px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{color:var(--muted);font-size:12px;font-weight:750;background:color-mix(in srgb,var(--panel) 88%,var(--bg))}tr:last-child td{border-bottom:0}.key{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.money{font-variant-numeric:tabular-nums}.usage{display:flex;align-items:center;gap:9px}.bar{width:130px;height:8px;border-radius:9px;background:var(--line);overflow:hidden}.fill{height:100%;background:var(--ok);transition:width .25s ease}.fill.warn{background:var(--warn)}.fill.danger{background:var(--danger)}.percent{min-width:45px;color:var(--muted);font-variant-numeric:tabular-nums}.status{font-weight:700}.status.ok{color:var(--ok)}.status.warn{color:var(--warn)}.status.danger{color:var(--danger)}.row-actions{display:flex;gap:7px}.row-actions button{padding:6px 9px;font-size:12px}.empty{padding:38px;text-align:center;color:var(--muted)}.foot{margin-top:12px;color:var(--muted);font-size:12px}dialog{width:min(500px,calc(100vw - 28px));padding:0;border:1px solid var(--line);border-radius:14px;background:var(--panel);color:var(--text);box-shadow:0 24px 70px rgb(0 0 0/.3)}dialog::backdrop{background:rgb(15 23 42/.48)}.dialog-body{padding:22px}.dialog-body h2{margin:0 0 5px;font-size:21px}.dialog-note{margin:0 0 16px;color:var(--muted)}.form-field{display:grid;gap:6px;margin:13px 0}.form-field[hidden],.check-field[hidden]{display:none}.form-field span{font-size:12px;font-weight:700;color:var(--muted)}.form-field input{width:100%;padding:10px 11px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text);font:inherit}.check-field{display:flex;align-items:center;gap:9px;margin:14px 0;color:var(--text);font-weight:650;cursor:pointer}.check-field input{width:17px;height:17px;accent-color:var(--accent)}.dialog-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}.dialog-error{min-height:20px;margin-top:10px;color:var(--danger);font-size:13px}@media(max-width:850px){.top{display:block}.actions{margin-top:14px}.panel{overflow:auto}}
@media(prefers-color-scheme:dark){:root{--bg:#0d1117;--panel:#161b22;--text:#e6edf3;--muted:#8b949e;--line:#30363d}.error{background:#2d1518;color:#ffb4b4;border-color:#6e3038}}
</style></head>
<body><main class="shell">
<div class="top"><div><h1>API Key 费用与额度</h1><div class="sub">按每次请求实际使用的模型和 Token 类型计算。查看、设置、修改和已用置零均不需要密码。</div></div><div class="actions"><a class="button" href="__DASHBOARD__">返回用量面板</a><button id="refresh">刷新</button><button id="add" class="primary">添加 / 设置 Key 额度</button></div></div>
<p class="notice">这里显示的是按 API 公开价格计算的等价费用/内部核算费用；使用 Codex Pro OAuth 时，它不等于一笔额外的 OpenAI API 账单。有限额 Key 遇到未定价模型会被暂停，防止通过换模型绕过额度。</p>
<div id="error" class="error"></div><section class="panel"><div id="content" class="empty">正在读取…</div></section><div id="foot" class="foot"></div>
</main>
<dialog id="quotaDialog"><form id="quotaForm" class="dialog-body"><h2 id="quotaDialogTitle">设置额度</h2><p id="quotaDialogNote" class="dialog-note"></p><label id="apiKeyField" class="form-field"><span>完整 API Key</span><input id="quotaAPIKey" type="password" autocomplete="off" placeholder="仅新增未观察到的 Key 时需要"></label><label id="labelField" class="form-field"><span>标签（可选）</span><input id="quotaLabel" type="text" maxlength="120" autocomplete="off"></label><label id="limitField" class="form-field"><span>最高额度（美元）</span><input id="quotaLimit" type="number" min="0.0001" max="1000000000" step="0.0001" inputmode="decimal"></label><label id="resetWithSaveField" class="check-field"><input id="resetWithSave" type="checkbox"><span>保存额度时，同时将当前已用额度置零</span></label><div id="quotaDialogError" class="dialog-error" role="alert"></div><div class="dialog-actions"><button id="cancelQuota" type="button">取消</button><button id="submitQuota" class="primary" type="submit">保存</button></div></form></dialog>
<script>
const statusURL='__STATUS__',manageURL='__MANAGE__',resetURL='__RESET__';let current=[],dialogMode='',dialogItem=null;
function usd(n){return '$'+Number(n||0).toFixed(4)}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function error(message){const el=document.getElementById('error');el.textContent=message||'';el.classList.toggle('show',!!message)}
async function json(url,options){const response=await fetch(url,Object.assign({cache:'no-store'},options||{}));const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||('HTTP '+response.status));return payload}
function render(data){current=Array.isArray(data.items)?data.items:[];const root=document.getElementById('content');if(!current.length){root.className='empty';root.innerHTML='还没有观察到 API Key。Key 至少成功产生一条用量记录后会自动出现，也可以点击“添加 / 设置 Key 额度”。';return}root.className='';let html='<table><thead><tr><th>API Key</th><th>标签</th><th>实际费用</th><th>最高额度</th><th>剩余额度</th><th>使用进度</th><th>价格覆盖</th><th>状态</th><th>操作</th></tr></thead><tbody>';current.forEach(item=>{const limited=!!item.limited,pct=limited&&item.limit_usd>0?Math.min(100,item.used_usd/item.limit_usd*100):0,barClass=pct>=100?'danger':pct>=80?'warn':'',missing=Number(item.unpriced_requests||0),blocked=!!item.blocked;html+='<tr><td class="key">'+esc(item.masked_key||'未识别')+'</td><td>'+esc(item.label||'—')+'</td><td class="money">'+usd(item.used_usd)+'</td><td class="money">'+(limited?usd(item.limit_usd):'无限制')+'</td><td class="money">'+(limited?usd(item.remaining_usd):'—')+'</td><td><div class="usage"><div class="bar"><div class="fill '+barClass+'" style="width:'+pct.toFixed(1)+'%"></div></div><span class="percent">'+(limited?pct.toFixed(1)+'%':'未设置')+'</span></div></td><td>'+(missing?'<span class="status warn">缺 '+missing+' 次</span>':'<span class="status ok">完整</span>')+'</td><td><span class="status '+(blocked?'danger':limited?'ok':'warn')+'">'+esc(blocked?(item.block_reason||'已暂停'):limited?'可用':'未限额')+'</span></td><td><div class="row-actions">'+(limited?'<button data-edit="'+esc(item.id)+'">修改额度</button><button class="danger" data-reset="'+esc(item.id)+'">已用置零</button>':'<button data-set="'+esc(item.id)+'">设置额度</button>')+'</div></td></tr>'});html+='</tbody></table>';root.innerHTML=html;document.getElementById('foot').textContent='更新时间：'+new Date(data.generated_at).toLocaleString()+' · 每 5 秒自动更新 · 费用基准：当前模型价格簿';}
async function load(){error('');try{render(await json(statusURL))}catch(e){error(e.message)}finally{document.getElementById('refresh').disabled=false}}
async function mutate(url,body){return json(url,{method:'GET',headers:{'X-Quota-Mutation':JSON.stringify(body)}})}
function openQuotaDialog(mode,item){dialogMode=mode;dialogItem=item||null;const reset=mode==='reset',fresh=mode==='new',dialog=document.getElementById('quotaDialog');document.getElementById('quotaDialogTitle').textContent=reset?'已用额度置零':fresh?'添加 Key 额度':item&&item.limited?'修改额度':'设置额度';document.getElementById('quotaDialogNote').textContent=reset?'将 '+(item.label||item.masked_key)+' 的当前已用额度置为 $0，并从现在重新累计；历史 Token 记录不会删除。':'正在设置 '+(item?item.label||item.masked_key:'新的 API Key')+' 的最高额度。';document.getElementById('apiKeyField').hidden=!fresh;document.getElementById('labelField').hidden=reset;document.getElementById('limitField').hidden=reset;document.getElementById('resetWithSaveField').hidden=reset||fresh;document.getElementById('resetWithSave').checked=false;document.getElementById('quotaAPIKey').value='';document.getElementById('quotaLabel').value=item&&item.label||'';document.getElementById('quotaLimit').value=item&&item.limited?String(item.limit_usd):'20';document.getElementById('quotaDialogError').textContent='';document.getElementById('submitQuota').textContent=reset?'确认置零':'保存额度';document.getElementById('submitQuota').className=reset?'danger':'primary';dialog.showModal();setTimeout(()=>document.getElementById(fresh?'quotaAPIKey':reset?'submitQuota':'quotaLimit').focus(),0)}
function closeQuotaDialog(){document.getElementById('quotaDialog').close();dialogMode='';dialogItem=null}
async function submitQuotaDialog(event){event.preventDefault();const submit=document.getElementById('submitQuota'),message=document.getElementById('quotaDialogError');let url=manageURL,body,resetAfterSave=false;if(dialogMode==='reset'){url=resetURL;body={id:dialogItem.id}}else{const limit=Number(document.getElementById('quotaLimit').value),label=document.getElementById('quotaLabel').value.trim();if(!Number.isFinite(limit)||limit<=0){message.textContent='额度必须是大于 0 的数字';return}body={label,limit_usd:limit};if(dialogMode==='new'){const apiKey=document.getElementById('quotaAPIKey').value.trim();if(!apiKey){message.textContent='请输入完整 API Key';return}body.api_key=apiKey}else{body.id=dialogItem.id;resetAfterSave=document.getElementById('resetWithSave').checked}}submit.disabled=true;message.textContent='';try{const saved=await mutate(url,body);if(resetAfterSave)await mutate(resetURL,{id:body.id||saved.id});closeQuotaDialog();await load()}catch(e){message.textContent=e.message}finally{submit.disabled=false}}
document.getElementById('refresh').onclick=()=>{document.getElementById('refresh').disabled=true;load()};document.getElementById('add').onclick=()=>openQuotaDialog('new');document.getElementById('content').onclick=e=>{const edit=e.target.closest('[data-edit]'),reset=e.target.closest('[data-reset]'),set=e.target.closest('[data-set]');if(edit)openQuotaDialog('edit',current.find(x=>x.id===edit.dataset.edit));else if(reset)openQuotaDialog('reset',current.find(x=>x.id===reset.dataset.reset));else if(set)openQuotaDialog('set',current.find(x=>x.id===set.dataset.set))};document.getElementById('quotaForm').onsubmit=submitQuotaDialog;document.getElementById('cancelQuota').onclick=closeQuotaDialog;load();setInterval(()=>{if(document.visibilityState==='visible')load()},5000);
</script></body></html>`

func quotaDashboardResponse(routes registeredRoutes) pluginapi.ManagementResponse {
	html := strings.NewReplacer(
		"__DASHBOARD__", routes.dashboardPath,
		"__STATUS__", routes.resourceQuotasPath,
		"__MANAGE__", routes.resourceQuotaSavePath,
		"__RESET__", routes.resourceQuotaResetPath,
	).Replace(quotaDashboardHTML)
	return pluginapi.ManagementResponse{
		StatusCode: http.StatusOK,
		Headers: http.Header{
			"Content-Type":  []string{"text/html; charset=utf-8"},
			"Cache-Control": []string{"no-store"},
		},
		Body: []byte(html),
	}
}
